import re
from collections import defaultdict

def parse_ini(text: str) -> dict[str, dict[str, str]]:
    def strip_whitespace(s: str) -> str:
        return s.strip()

    def parse_value(value: str) -> str:
        if value.startswith('"') and value.endswith('"'):
            return value[1:-1]
        return value

    def parse_line(line: str, section: str, section_dict: dict[str, str], default_dict: dict[str, str]) -> None:
        line = line.strip()
        if not line or line.startswith((';', '#')):
            return
        if '=' in line:
            key, value = line.split('=', 1)
        elif ':' in line:
            key, value = line.split(':', 1)
        else:
            raise ValueError(f"Malformed line: {line}")
        key = key.strip().lower()
        value = parse_value(value.strip())
        if key in section_dict:
            section_dict[key] += f"\n{value}"
        else:
            section_dict[key] = value

    def interpolate_value(value: str, section: str, sections: dict[str, dict[str, str]]) -> str:
        def interpolate(match: re.Match) -> str:
            key = match.group(1)
            if ':' in key:
                sec, key = key.split(':', 1)
                if sec not in sections or key not in sections[sec]:
                    raise KeyError(f"Missing key: {sec}:{key}")
                return sections[sec][key]
            if key not in sections[section]:
                raise KeyError(f"Missing key: {key}")
            return sections[section][key]

        def recursive_interpolate(value: str) -> str:
            try:
                return re.sub(r'\$\{([^}]+)\}', interpolate, value)
            except KeyError as e:
                raise ValueError(f"Interpolation error: {e}")
            except ValueError as e:
                raise ValueError(f"Interpolation cycle detected: {e}")

        return recursive_interpolate(value)

    lines = text.splitlines()
    sections = {}
    current_section = None
    default_section = {}
    default_set = set()

    for line in lines:
        stripped_line = line.strip()
        if stripped_line.startswith('[') and stripped_line.endswith(']'):
            if current_section and not default_set:
                raise ValueError(f"Key line before any section header: {line}")
            section_name = stripped_line[1:-1].strip()
            if section_name == 'DEFAULT':
                current_section = 'DEFAULT'
            else:
                current_section = section_name
                sections[current_section] = defaultdict(str)
            continue

        if not current_section:
            raise ValueError(f"Key line before any section header: {line}")

        if current_section == 'DEFAULT':
            parse_line(line, current_section, default_section, default_section)
            default_set.add(line.strip().lower())
        else:
            parse_line(line, current_section, sections[current_section], default_section)

    for section in sections:
        for key, value in sections[section].items():
            try:
                sections[section][key] = interpolate_value(value, section, sections)
            except KeyError as e:
                raise ValueError(f"Interpolation error: {e}")
            except ValueError as e:
                raise ValueError(f"Interpolation cycle detected: {e}")

    return {k: dict(v) for k, v in sections.items() if k != 'DEFAULT'}
