from collections import OrderedDict
from typing import Callable, Any, Optional

class TTLCache:
    def __init__(self, capacity: int, ttl: float, clock: Callable[[], float]):
        self.capacity = capacity
        self.ttl = ttl
        self.clock = clock
        self.cache = OrderedDict()
        self.hits = 0
        self.misses = 0
        self.evictions = 0
        self.expirations = 0

    def _cleanup(self):
        now = self.clock()
        keys_to_remove = []
        for key, (value, expiry) in self.cache.items():
            if now >= expiry:
                keys_to_remove.append(key)
        for key in keys_to_remove:
            del self.cache[key]
            self.expirations += 1

    def put(self, key: Any, value: Any):
        if self.capacity == 0:
            return
        now = self.clock()
        self._cleanup()
        if key in self.cache:
            del self.cache[key]
        elif len(self.cache) >= self.capacity:
            self.cache.popitem(last=False)
            self.evictions += 1
        self.cache[key] = (value, now + self.ttl)

    def get(self, key: Any, default: Optional[Any] = None) -> Any:
        if self.capacity == 0:
            self.misses += 1
            return default
        now = self.clock()
        self._cleanup()
        if key in self.cache:
            value, expiry = self.cache.pop(key)
            if now < expiry:
                self.cache[key] = (value, expiry)
                self.hits += 1
                return value
            else:
                self.expirations += 1
                self.misses += 1
                return default
        else:
            self.misses += 1
            return default

    def __len__(self) -> int:
        now = self.clock()
        return sum(1 for value, expiry in self.cache.values() if now < expiry)

    def stats(self) -> dict:
        return {
            "hits": self.hits,
            "misses": self.misses,
            "evictions": self.evictions,
            "expirations": self.expirations
        }
