def summarize_ranges(nums: list[int]) -> str:
    if not nums:
        return ""

    nums = sorted(set(nums))
    ranges = []
    start = nums[0]

    for i in range(1, len(nums)):
        if nums[i] == nums[i - 1] + 1:
            continue
        if nums[i - 1] - start >= 2:
            ranges.append(f"{start}..{nums[i - 1]}")
        elif nums[i - 1] - start == 1:
            ranges.append(f"{start},{nums[i - 1]}")
        else:
            ranges.append(f"{nums[i - 1]}")
        start = nums[i]

    if nums[-1] - start >= 2:
        ranges.append(f"{start}..{nums[-1]}")
    elif nums[-1] - start == 1:
        ranges.append(f"{start},{nums[-1]}")
    else:
        ranges.append(f"{nums[-1]}")

    return ",".join(ranges)
